import{_ as e,o as t,c as n,a5 as i}from"./chunks/framework.CINlqUGR.js";const h=JSON.parse('{"title":"更新日志 · XiHan.UI","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1787749455000}'),c={name:"changelog.md"};function r(d,o,l,s,a,g){return t(),n("div",null,[...o[0]||(o[0]=[i('<h1 id="更新日志-·-xihan-ui" tabindex="-1">更新日志 · XiHan.UI <a class="header-anchor" href="#更新日志-·-xihan-ui" aria-label="Permalink to &quot;更新日志 · XiHan.UI&quot;">​</a></h1><p>本文件记录 XiHan.UI 各版本的变更。每条标注 <strong>新增 / 修复 / 优化 / 调整 / 移除</strong> 类别。库以 npm 包形式发布，17 个公开包锁步同版；升级前请留意「调整」类中的破坏性变更。</p><h2 id="v1-0-0-2026-08-26" tabindex="-1">v1.0.0 (2026-08-26) <a class="header-anchor" href="#v1-0-0-2026-08-26" aria-label="Permalink to &quot;v1.0.0 (2026-08-26)&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">版本与兼容性</p><p>首个正式版。从这一版起，<a href="/guide/versioning">版本与兼容性政策</a>的全部条款生效——导出名、prop、部件与 <code>data-*</code> 属性、CSS 令牌与 <code>@layer</code> 名、自定义元素标签，改名与删除一律走主版本。</p><p>尚未提供：内建语言包（组件文案只内建英文，中文等要自备 <code>translations</code>，全局注入口已就绪）、令牌浏览器、AI 组件族的 MarkdownStream / Reasoning 与 ToolCall 折叠 / 工具审批、企业业务组件。</p></div><ul><li><strong>新增</strong> 框架无关的无头内核：一个组件的状态、交互与无障碍逻辑住在 <code>@xihan-ui/headless</code>，适配器只把 <code>connect()</code> 产出的属性挂到宿主元素上；同一份内核在 Vue 与 Web Components 两端跑同一套一致性套件，逐帧比对归一化后的 DOM</li><li><strong>新增</strong> 样式与逻辑解耦：皮肤只认 <code>data-scope</code> / <code>data-part</code> / <code>data-*</code> 状态属性，不认框架、不认类名，整包换皮肤不用碰一行 JS</li><li><strong>新增</strong> 17 个公开包由 changesets 的 <code>fixed</code> 组锁步同版，运行时第三方依赖只有一个（<code>@internationalized/date</code>，仅日期族使用）；浮层定位、虚拟滚动、代码着色、流式 Markdown、Web Components 响应式基类均为自研</li><li><strong>新增</strong> <code>@xihan-ui/kernel</code> 结构原语：anatomy、<code>mergeProps</code>、<code>normalizeProps</code>、Scope、context、id；另有运行期锁步版本检查（混装两个版本在 dev 下报 <code>core.version-mismatch</code>）与框架元数据</li><li><strong>新增</strong> <code>@xihan-ui/machine</code> 状态机运行时：<code>createMachine</code>、解释器契约、受控 / 非受控值绑定</li><li><strong>新增</strong> <code>@xihan-ui/behavior</code> 行为原语：消解层、焦点域、滚动锁、进出场、集合、typeahead、悬停意图、滚动跟随与粘底</li><li><strong>新增</strong> <code>@xihan-ui/motion</code> 动效原语：缓动单一真源、纯补间、帧循环、减弱动效偏好、解析解弹簧、Web Animations 薄封装</li><li><strong>新增</strong> <code>@xihan-ui/position</code> 浮层定位：放置、翻转、贴边、箭头锚点、rtl，自研无第三方依赖</li><li><strong>新增</strong> <code>@xihan-ui/vue</code> Vue 3 适配器，729 个部件：受控 / 非受控、<code>v-model</code>、带类型的作用域插槽；<code>behavior</code> 子入口收五个行为原语的组合式；命令式服务四件（轻提示、通知、对话框 <code>confirm</code> / <code>prompt</code>、顶部进度条），配置源与文案可运行期换</li><li><strong>新增</strong> <code>@xihan-ui/web-components</code> 适配器，121 个自定义元素：元素不生成结构，作者写带 <code>data-xh-part</code> 的 Light DOM 子节点，元素把 <code>connect()</code> 产出打上去；运行期增删子节点会重新接线；随包出 <code>custom-elements.json</code></li><li><strong>新增</strong> 119 个组件，每个同时产出无头内核、Vue 组件、自定义元素与默认皮肤，行为由内核唯一定义</li><li><strong>新增</strong> 通用 15 个：按钮、按钮组、剪贴板、下载触发器、文本省略、浮动按钮、渐变文字、快捷键、图标、图标块、滚动条、切换按钮、切换按钮组、排印、水印</li><li><strong>新增</strong> 布局 8 个：弹性布局、栅格、布局、瀑布流、滚动区域、分隔线、间距、分栏</li><li><strong>新增</strong> 导航 16 个：固钉、锚点、回到顶部、面包屑、右键菜单、菜单、菜单栏、导航菜单、页头、分页、分段控制器、侧栏导航、步骤条、标签页、工具栏、引导</li><li><strong>新增</strong> 数据录入 32 个：级联选择、复选框、复选框组、颜色选择器、组合框、日期输入、日期选择器、动态录入、就地编辑、表单字段、字段集、文件上传、表单、图片裁切、列表框、提及、数字输入、密码输入、分格输入、弹出选择、单选组、评分、选择器、签名板、滑块、开关、标签输入、文本输入、时间输入、时间选择器、穿梭框、树选择</li><li><strong>新增</strong> 数据展示 30 个：手风琴、头像、头像组、日历、卡片、走马灯、代码块、折叠区域、倒计时、描述列表、空状态、热力图、文本高亮、图片、图片预览、无限滚动、JSON 视图、列表、日志、跑马灯、数值动画、二维码、统计数值、表格、标签、时间、时间线、计时器、树、虚拟滚动</li><li><strong>新增</strong> 反馈 9 个：警告提示、徽标、加载条、进度条、结果页、骨架屏、加载指示器、通知、轻提示</li><li><strong>新增</strong> 浮层 7 个：对话框、抽屉、浮动面板、悬浮卡片、弹出确认、气泡卡片、文字提示</li><li><strong>新增</strong> AI 对话 2 个：消息编辑器、会话线程</li><li><strong>新增</strong> <code>@xihan-ui/tokens</code> 设计令牌：源是 DTCG，构建期产出 CSS 变量——原语 95、语义 158，另有紧凑 49、浅色 41、深色 44、减弱动效 8 条覆盖，运行时不做 CSS-in-JS</li><li><strong>新增</strong> <code>@xihan-ui/styles</code> 默认皮肤 125 份，按 <code>@layer</code> 分层（<code>xihan.reset</code> → <code>tokens</code> → <code>base</code> → <code>components</code> → <code>overrides</code>），使用者的覆盖恒排在最后</li><li><strong>新增</strong> 三条视觉轴：<code>variant</code> 管形态、<code>tone</code> 管语气（六族）、<code>size</code> 管尺寸；语气色共享一层，实心底上的前景与交互态挪动方向由语气色按 WCAG 相对亮度现推，换肤下配对自动成立</li><li><strong>新增</strong> 主题五个维度独立切换：明暗、品牌、密度、对比度、书写方向，带 <code>createThemeController</code> 与品牌色派生</li><li><strong>新增</strong> 兜底字形二十个 <code>--xh-glyph-mark-*</code> 令牌，构建期内联图标包 SVG，跨系统长相一致</li><li><strong>新增</strong> 浮层一律 Teleport 到单一落点 <code>#xh-portal-root</code>，层号不受宿主祖先的层叠上下文影响；13 个滚动宿主自带自绘滚动条，浮在内容之上不占宽度</li><li><strong>新增</strong> <code>@xihan-ui/animations</code> 可序列化的动效配方、内置进场与注意动效、错开起播、文字拆分</li><li><strong>新增</strong> <code>@xihan-ui/sound</code> 纯 Web Audio 程序化 UI 音效，零音频文件，三套主题</li><li><strong>新增</strong> <code>@xihan-ui/backgrounds</code> WebGL2 效果与数据驱动的粒子云，框架无关</li><li><strong>新增</strong> <code>@xihan-ui/icons</code> 首方图标集，<code>IconRecord</code> 结构化记录、渲染端逐节点建元素，运行期不解析 SVG 字符串；另有 SVG → <code>IconRecord</code> 的构建期转换器，可把任意 SVG 目录转成可摇树的运行期模块</li><li><strong>新增</strong> <code>@xihan-ui/chat-stream</code> AI 协议内核：SSE 读取 → 协议归一 → parts 归约 → 会话 store，零 DOM、零框架</li><li><strong>新增</strong> <code>@xihan-ui/markdown</code> 流式 Markdown 渲染内核：增量切块 + 稳定 key + 消毒，CommonMark 子集一致率 489/652</li><li><strong>新增</strong> <code>@xihan-ui/code-highlight</code> 代码着色，自研粗粒度词法器</li><li><strong>新增</strong> 键盘交互依 W3C APG 落地，77 份机读键盘规格表共 463 行键位，它同时是测试的分母：少覆盖一行即判套件失败</li><li><strong>新增</strong> 无障碍扫描跑在真实 Chromium（axe），存量违规登记表只剩两条，另有一条 breadcrumb 的步骤重放豁免；焦点环、按下反馈、禁用态对比度与语气配色（2 档主题 × 6 族，158 组配对）都由门禁逐条守住</li><li><strong>新增</strong> 119 个组件都留了文案位并挂进覆盖表，全局 <code>ConfigProvider</code> 一处注入；日期族的默认语言跟随宿主；书写方向用逻辑属性写，rtl 下浮层放置、方向键语义与图形朝向一并对调</li><li><strong>新增</strong> 24 个表单字段组件认原生表单重置，11 个单一控件封装把字段状态与字段标签接到真控件上；<code>field</code> 提供标签、描述、错误与 <code>asChild</code> 逃生口</li><li><strong>新增</strong> <code>pnpm gate</code> 一条命令跑 67 项结构检查：令牌产物、层序、皮肤在场、部件接线、浮层策略、聚焦环、语气对比度、键盘套件、导出、角色组、文档数字对账等，生成物一律由门禁核对</li><li><strong>新增</strong> 单元与跨适配器一致性用例 10089 条；真实浏览器另跑无障碍扫描、浮层定位契约与 Web Components 示例</li><li><strong>新增</strong> 体积棘轮 27 条产物限额，摇树是真的：只引一枚图标 149 B、整集合 7.37 kB，<code>XhButton</code> 1.38 kB、<code>XhDialogRoot</code> 15 kB（均 gzip）</li><li><strong>新增</strong> 产物契约由 <code>publint</code> + <code>attw</code> 守住；ESM-only，子路径导出都带类型</li><li><strong>新增</strong> 组件文档由 headless 产物与 TS 类型生成，示例引的是真实组件，Vue 与 Web Components 两套写法并排</li><li><strong>调整</strong> 元数据的宿主行不再报锁步一致性，只报宿主与版本</li></ul><h2 id="v1-0-0-preview-0-2026-08-26" tabindex="-1">v1.0.0-preview.0 (2026-08-26) <a class="header-anchor" href="#v1-0-0-preview-0-2026-08-26" aria-label="Permalink to &quot;v1.0.0-preview.0 (2026-08-26)&quot;">​</a></h2><p>45 份变更集，17 个公开包锁步同版，走 <code>preview</code> dist-tag。</p><p>这一版的主线是<strong>把 alpha 里遗留的形状问题一次改完</strong>：两对做着同一件事的组件分家（toast / notification、badge / tag），三处与同族对不上的 prop 名归位，语气色从逐族写死改为按底色现推。</p><ul><li><p><strong>新增</strong> <code>notification</code> 组件，与 <code>toast</code> 分家：前者是系统推来的卡片（左侧类型字形、右上角关闭钮、两列网格、九宫格落位），后者收窄成操作反馈（顶部居中、宽度包着内容、一行图标加一句话）</p></li><li><p><strong>新增</strong> 分页的省略号能摊开：折进去的那几页有了入口，分页因此升级成浮层族（新增 <code>positioner</code> / <code>content</code>）；每页条数从只读 prop 升成真状态，配 <code>XhPaginationPageSizeSelect</code> 与 <code>pageSizeOptions</code></p></li><li><p><strong>新增</strong> 表格的前缀列（行号 / 勾选 / 展开，按给定顺序插在最前并占住列号）、树形子行，以及一份可序列化的列偏好（列序 / 隐藏列 / 列宽）</p></li><li><p><strong>新增</strong> 树的 <code>multiple</code>、<code>leafOrientation</code>（末端全是叶子的那层横排）与节点级 <code>childrenOrientation</code></p></li><li><p><strong>新增</strong> json-viewer 的原文视图 <code>view=&quot;text&quot;</code>：直接出缩进过的 JSON，可整段拷走，值不再受截断与折减</p></li><li><p><strong>新增</strong> 13 个宿主的滚动层自带自绘滚动条：12 个浮层族的 <code>content</code> 与 json-viewer 的两档，作者一个部件都不用写；滚动条同时新增 <code>scroll-hover</code> 档并定为缺省</p></li><li><p><strong>新增</strong> Vue 侧三条逃生口：<code>@xihan-ui/vue/behavior</code> 子入口（五个行为原语的组合式）、<code>useHotkeys</code>（只注册不渲染键帽）、<code>XhFieldControl</code> 的 <code>asChild</code> 与配套 <code>useFieldControl</code></p></li><li><p><strong>新增</strong> 命令式服务补齐三件：<code>createLoadingBarService</code>（句柄上是在途计数而不是布尔开关）、取值型 <code>prompt</code>、配置源可运行期换（应用切语言后服务子树跟着变）</p></li><li><p><strong>新增</strong> <code>@xihan-ui/tokens</code> 导出颜色能力：相对亮度、对比度、择色、混色与深浅——这套数学此前在四处各写了一份，判据各走各的</p></li><li><p><strong>新增</strong> date-picker 的 <code>defaultFocusedValue</code>，决定展开时先落在哪一页</p></li><li><p><strong>新增</strong> thread 补 <code>provideThread</code> / <code>useThreadContext</code>，与孪生组件 log 对称</p></li><li><p><strong>调整</strong> <strong>badge 收窄成「只做角标」</strong>：删掉 <code>variant</code>，解剖从单层 <code>root</code> 拆成 <code>root</code>（锚点）+ <code>indicator</code>（角标），新增 <code>placement</code>，定位归组件自己管。<strong>行内的状态药丸请改用 <code>tag</code></strong></p></li><li><p><strong>调整</strong> <strong>生命周期相位改走 <code>data-state</code></strong>，<code>data-status</code> 退回「结果种类」一轴——此前一条 <code>[data-status=&#39;error&#39;]</code> 会同时命中「加载失败的头像」和「一整页 500 报错」</p></li><li><p><strong>调整</strong> 树的 <code>selectionMode</code> 转为 <code>multiple</code> 的旧写法，与同族七家对齐</p></li><li><p><strong>调整</strong> 实心底上的前景色与交互态挪动方向改由语气色现推（WCAG 相对亮度，白字黑字的交叉点 <code>0.179</code> 是解析解），换肤下配对自动成立；装饰档 <code>--xh-_tone-soft</code> 从 500 提到与控件边界同一档，六族十二组都够到 3:1</p></li><li><p><strong>调整</strong> 描边档的标签改用「可操作区边界」那一档语气色，边相对面的对比从 1.44–2.18 抬到 4.56–7.83（浅色）</p></li><li><p><strong>调整</strong> 浮层里的条目之间加 2px 行距，新增语义令牌 <code>--xh-list-option-gap</code> 统一这把尺——此前库内自己就有 0 / 2 / 4px 三种方言</p></li><li><p><strong>调整</strong> select 的盒不再自带 320px 宽度上限，框宽交回布局</p></li><li><p><strong>调整</strong> 上一页 / 下一页默认就画两枚箭头，不再要每份示例手写「上一页 / 下一页」四个字</p></li><li><p><strong>调整</strong> 147 个注入键改用 <code>Symbol.for</code>：模块被加载成两份时不再整棵子树白屏</p></li><li><p><strong>修复</strong> 点字段的标题聚不到复合控件的焦点；套进字段的复合控件读屏<strong>一个名字都没有</strong>——标签的 <code>for</code> 指向 <code>div</code> 时什么也不会发生，而且不报错</p></li><li><p><strong>修复</strong> <code>useStickToBottom</code> 吞掉句柄，最常见的用法（两个 getter 读模板 ref）下根本没挂上</p></li><li><p><strong>修复</strong> <code>XhJsonViewerRoot</code> 的 <code>value</code> 在类型上被推成 <code>undefined</code>，任何跑 vue-tsc 的工程传真实数据都编译不过</p></li><li><p><strong>修复</strong> 命令式服务的宿主挂不起来时连累调用方：一条轻提示能让整次导航失败、整站白屏，现在退化成空操作并发一条说得清的诊断</p></li><li><p><strong>修复</strong> 日历的「大步翻」两颗钮被一条 <code>display: none</code> 无条件收掉，从来就没画出来过</p></li><li><p><strong>修复</strong> date-picker 展开态初值为真且铺了格子时抛 <code>SEND_BEFORE_MOUNT</code></p></li><li><p><strong>修复</strong> 条目之间一有缝，select / combobox / popselect 的高亮就一跨一闪，读屏跟着一路播报</p></li><li><p><strong>修复</strong> 四处被祖先 <code>overflow</code> 裁掉的聚焦环改成往内收</p></li><li><p><strong>修复</strong> 树上三个对读屏隐藏的把手不再被指针聚焦（浏览器告警「aria-hidden 的后代仍持有焦点」）；叶子行补上箭头那一格的缩进，层级关系读得出来了</p></li><li><p><strong>修复</strong> 菜单族两家（context-menu / menubar）的勾选标记没跟着语气走</p></li><li><p><strong>优化</strong> 不可关闭的标签走快路不建状态机：400 枚从 39.1ms 降到 18.3ms</p></li><li><p><strong>优化</strong> 进度条服务的宿主自己渲染，不再经 provide/inject 拿 api</p></li><li><p><strong>移除</strong> <code>toaster</code>：轻提示不再需要额外的容器组件</p></li><li><p><strong>移除</strong> <code>@xihan-ui/kernel</code> 的 <code>DATA_SCROLL_SHARD</code>：配套的分片机制从未实现，声明处之外全库零引用</p></li></ul><h2 id="v1-0-0-alpha-3-2026-08-23" tabindex="-1">v1.0.0-alpha.3 (2026-08-23) <a class="header-anchor" href="#v1-0-0-alpha-3-2026-08-23" aria-label="Permalink to &quot;v1.0.0-alpha.3 (2026-08-23)&quot;">​</a></h2><p>40 份变更集，17 个公开包锁步同版。这一版的主线是<strong>一致性收口</strong>：把「同一件事在不同组件里有几种做法」逐条查出来、裁一种、再写成门禁钉住。结构门禁从 21 道增到 57 道。</p><ul><li><p><strong>新增</strong> <code>scrollbar</code> 组件：自绘滚动条可以挂在任意一个滚动容器上，不必是本组件的后代</p></li><li><p><strong>新增</strong> <code>date-picker</code> / <code>time-picker</code> 的快捷选项（<code>presets</code>）：给数据就在浮层里多排一列，自成一套 listbox 键盘</p></li><li><p><strong>新增</strong> 日历的多面板、按月 / 季度 / 年 / 周挑、快速翻年、周选整周预览；周序号成为一等部件 <code>week-number</code></p></li><li><p><strong>新增</strong> select 浮层的底部操作区，「新建」「全选」这类按钮有了位置</p></li><li><p><strong>新增</strong> 热力图的 <code>palette</code> 色板轴（六色），与语气轴各管各的</p></li><li><p><strong>新增</strong> number-field 的 <code>parse</code> / <code>format</code> 与可选 <code>control</code> 部件；pin-input 的 <code>pattern</code></p></li><li><p><strong>新增</strong> 全局配置做成真正的 ConfigProvider：全局默认 + 局部覆盖，两个适配器一份语义</p></li><li><p><strong>调整</strong> <strong>浮层搬进单一落点</strong>：19 个浮层的 positioner 一律 Teleport 到 <code>#xh-portal-root</code>。宿主祖先只要建了层叠上下文，原地渲染的浮层层号就退化成局部序号——这是库无法从自身约束的。<strong>按 <code>wrapper.querySelector</code> 取浮层节点的代码要改从 <code>document</code> 取</strong></p></li><li><p><strong>调整</strong> <strong>盒的定义统一</strong>：有 <code>control</code> 部件就是盒，<code>trigger</code> 退化成盒内的 <code>flex: 1</code> 按钮。此前 16 个输入 / 选择控件有三种盒，盒是 <code>&lt;button&gt;</code> 的那五家没法把清空钮放进框里</p></li><li><p><strong>调整</strong> <strong>清空 / 关闭 / 移除按钮收成四类契约</strong>：焦点模型、空态、尺寸、圆角、互斥、文案键、键盘路径逐条统一；select / cascader / tree-select / popselect 补上了此前完全缺席的键盘清空</p></li><li><p><strong>调整</strong> <strong>状态属性收成一套词汇</strong>：当前项一律 <code>data-current</code>，<code>data-active</code> 的一名三义拆成 <code>data-in-path</code> 与 <code>data-passed</code>，组级混合态归 <code>checked | unchecked | indeterminate</code></p></li><li><p><strong>调整</strong> <strong>默认语言跟随运行时</strong>：日期系兜底从写死 <code>zh-CN</code> 改成「显式 locale → 全局配置 → 宿主语言 → <code>en-US</code>」。<strong>默认周首日随之从周一变成周日</strong>，要固定就显式传 <code>locale</code> 或 <code>firstDayOfWeek</code></p></li><li><p><strong>调整</strong> 「移除这一枚 chip / 这一行」统一叫 <code>item-delete-trigger</code>，四个文案键归成 <code>deleteItem</code></p></li><li><p><strong>调整</strong> 选择态一族（table / tree / transfer）的选中集合统一叫 <code>selection</code>，载荷键统一 <code>{ value }</code></p></li><li><p><strong>调整</strong> 兜底字形改用真图标（<code>--xh-glyph-mark-*</code> 二十个令牌），不再是跨系统长相各异的 Unicode 字符</p></li><li><p><strong>调整</strong> 减弱动效只剩一条通道，CSS 侧新增 <code>[data-motion=&#39;reduce&#39;]</code> 钩子；缓动与时长的真源是令牌</p></li><li><p><strong>调整</strong> 并排成对的面板定高——穿梭框搬走条目后整体不再变矮</p></li><li><p><strong>调整</strong> 菜单族三家（menu / menubar / context-menu）逐条同值：menubar 此前根本没有「子菜单触发项展开态」这条规则</p></li><li><p><strong>修复</strong> side-nav 折叠成图标栏后，行按钮与链接<strong>没有可及名</strong>——读屏用户完全不知道每一项是什么（真机 axe 扫出，critical）</p></li><li><p><strong>修复</strong> date-picker / time-picker / combobox 有值时下拉钮被藏掉：鼠标用户没有打开入口，Escape 收起时焦点掉到 <code>body</code></p></li><li><p><strong>修复</strong> 日历周序号在周日起算时整列少 1（ISO 周里周日属于上一周）</p></li><li><p><strong>修复</strong> <code>TimeProps.locale</code> 的窄联合与全局 BCP 47 locale 对不上，配 <code>de-DE</code> 会拿到中文用词</p></li><li><p><strong>修复</strong> 4 条子路径导出的类型文件根本不存在，<code>publint</code> / <code>attw</code> 判红——发布链路当场卡住</p></li><li><p><strong>优化</strong> 无障碍：真机 axe 覆盖到 dialog / drawer / image-viewer 三个模态，全部通过</p></li><li><p><strong>优化</strong> 新增 37 道门禁，其中 <code>check-doc-numbers</code> 把「文档里写死的数字」变成可判的——README 与文档站的组件数、令牌数、门禁道数不会再各说各话</p></li><li><p><strong>优化</strong> 版本策略页按实测重算：<code>data-state</code> 取值清单删掉 4 个库里已不存在的，WC 命令式方法从 22 条改成 29 条</p></li></ul><h2 id="v1-0-0-alpha-2-2026-08-16" tabindex="-1">v1.0.0-alpha.2 (2026-08-16) <a class="header-anchor" href="#v1-0-0-alpha-2-2026-08-16" aria-label="Permalink to &quot;v1.0.0-alpha.2 (2026-08-16)&quot;">​</a></h2><p>13 份变更集，17 个公开包锁步同版。<code>@xihan-ui/motion</code> 与 <code>@xihan-ui/animations</code> 是新包，这一版首次发布。</p><ul><li><p><strong>新增</strong> <code>@xihan-ui/motion</code> 动效原语与 <code>@xihan-ui/animations</code> 现成动效两个包，并补齐动效地基的四个缺口</p></li><li><p><strong>新增</strong> <code>@xihan-ui/icons</code> 的 SVG → <code>IconRecord</code> 构建期转换器：<code>xihan-icons</code> 命令与 <code>@xihan-ui/icons/codegen</code> 子路径，把任意 SVG 目录转成可摇树的运行期模块</p></li><li><p><strong>新增</strong> 首方图标集扩到覆盖中后台界面的常用语义，共 179 枚手绘图标，分九类；只引一枚仍是 149 B（gzip），集合变大不影响你的产物</p></li><li><p><strong>新增</strong> 自定义元素的全局文案层 <code>setXhConfig()</code></p></li><li><p><strong>新增</strong> <code>startSkinCheck()</code> 开发期探测与 <code>styles.missing-skin</code> 诊断码——漏引皮肤不再静默</p></li><li><p><strong>新增</strong> <code>check-style-entries</code> 门禁：每份皮肤都必须进得了全量入口、也够得着按需入口</p></li><li><p><strong>优化</strong> 75 个组件的插槽写上真类型，<code>vue-tsc</code> 从此接得住插槽名与载荷键名的拼写错误</p></li><li><p><strong>优化</strong> 104 个组件全部留出 <code>&lt;Comp&gt;Translations</code> 的位，哪怕眼下一句文案都没有——后面要加时不必改结构</p></li><li><p><strong>优化</strong> 每份皮肤都能单独引入，动画不再指望别处的文件在场</p></li><li><p><strong>修复</strong> 官网作为第一个真实消费方落地时暴露的四条问题（宿主定位、图层序等），全部改代码而非只改文档</p></li><li><p><strong>调整</strong> 「collection 铺开的结构凑齐必备部件」由人工判据改成机检，三档语义写进文档</p></li><li><p><strong>调整</strong> 体积棘轮改成量使用者真正下载的那个数</p></li></ul><h2 id="v1-0-0-alpha-1-2026-08-13" tabindex="-1">v1.0.0-alpha.1 (2026-08-13) <a class="header-anchor" href="#v1-0-0-alpha-1-2026-08-13" aria-label="Permalink to &quot;v1.0.0-alpha.1 (2026-08-13)&quot;">​</a></h2><p>25 份变更集，15 个公开包锁步同版。<code>@xihan-ui/sound</code> 是新包，这一版首次发布；<code>@xihan-ui/icons</code> 在上一版没能发出去，这一版补齐。</p><ul><li><p><strong>新增</strong> <code>@xihan-ui/sound</code> 声音层：纯 Web Audio 的程序化 UI 音效，零音频文件、零第三方依赖、框架无关；命令式反馈服务已接上</p></li><li><p><strong>新增</strong> 进度条的环形与仪表盘两种形态（<code>variant</code> 由 <code>line</code> 扩成 <code>line</code> / <code>circle</code> / <code>dashboard</code>）</p></li><li><p><strong>新增</strong> 级联选择的空态兜底：<code>empty</code> 部件、<code>data-empty</code> 标记与文案覆盖</p></li><li><p><strong>新增</strong> checkbox / switch / combobox / color-picker 能进 HTML 表单，表单字段组件由 18 个变 20 个，五个缺口清完</p></li><li><p><strong>新增</strong> 复合控件响应表单重置：机制本体加 17 个组件全部接上，另立一道门禁盯着以后新加的；Web Components 侧同步</p></li><li><p><strong>新增</strong> <code>--xh-border-control</code> / <code>--xh-border-control-hover</code> 两支控件边界令牌，<code>data-contrast</code> 随之接上</p></li><li><p><strong>新增</strong> popconfirm 与 float-button 的组件文档页第一次有了 Props 表</p></li><li><p><strong>修复</strong> 摇树第一次真的生效：只用一个组件不再拖来整个库。此前七个库包都是单入口打包，500+ 模块被摊平进一份 <code>dist/index.js</code>，<code>sideEffects: false</code> 随之失效。实测只用 <code>XhBadge</code> 由 168,947 B 降到 <strong>538 B</strong></p></li><li><p><strong>修复</strong> RTL 下浮层的 <code>start</code> / <code>end</code> 第一次真的翻过来</p></li><li><p><strong>修复</strong> 浮层箭头指向锚点，不再钉死在浮层中点</p></li><li><p><strong>修复</strong> <code>index.css</code> 的级联层序：层序声明挪到入口最顶，此前令牌与部分组件皮肤抢先立层</p></li><li><p><strong>修复</strong> 四处只在真实宿主里才现形的缺陷（含首屏即展开的对话框与抽屉能服务端直出、无 window 的宿主里不再抛异常）</p></li><li><p><strong>修复</strong> 带语气的 outline 控件边框补到 3:1，控件边界切到 <code>border.control</code>，WCAG SC 1.4.11 第一次真的达标</p></li><li><p><strong>修复</strong> 补齐 4 处「边框改不动」的覆盖槽</p></li><li><p><strong>修复</strong> combobox 展开按钮翻面只转箭头字形，不再带着悬停底色一起转</p></li><li><p><strong>修复</strong> 级联选择的空态占位在 Web Components 侧补齐，两个适配器不再分叉</p></li><li><p><strong>调整</strong> 跨组件已经分叉的名字统一回一套（7 处）。part 名与 prop 名在 1.0 之后就是公开 API，趁 alpha 一次改完，逐条迁移点见各包 CHANGELOG</p></li><li><p><strong>调整</strong> 下拉与列表族的条目度量与高亮档位统一成两档制，分两批铺完 12 个组件</p></li><li><p><strong>调整</strong> 级联选择皮肤翻修：展开路径改品牌淡底加粗、分支条目补右向箭头、列改内容撑宽定高</p></li><li><p><strong>调整</strong> <code>hideOutside</code> 的入参形状随真实宿主那四处修复一并变化</p></li></ul><h2 id="v1-0-0-alpha-0-2026-08-11-·-框架无关重写" tabindex="-1">v1.0.0-alpha.0 (2026-08-11) · 框架无关重写 <a class="header-anchor" href="#v1-0-0-alpha-0-2026-08-11-·-框架无关重写" aria-label="Permalink to &quot;v1.0.0-alpha.0 (2026-08-11) · 框架无关重写&quot;">​</a></h2><h3 id="基座" tabindex="-1">基座 <a class="header-anchor" href="#基座" aria-label="Permalink to &quot;基座&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/kernel</code> 结构原语：anatomy、<code>mergeProps</code>、<code>normalizeProps</code>、Scope、context、id 生成，以及浮层定位、虚拟滚动、代码着色三个端口的类型契约</li><li><strong>新增</strong> <code>@xihan-ui/machine</code> 自研薄状态机：定义层、<code>createService</code> 解释器与 vanilla 运行时，受控值绑定与效应生命周期</li><li><strong>新增</strong> <code>@xihan-ui/behavior</code> 交互行为原语：消解层、焦点域、滚动锁、进出场，随后补上条目集合导航（roving tabindex 底座）与首字母连打检索</li><li><strong>新增</strong> <code>@xihan-ui/tokens</code> 设计令牌体系与主题运行时，令牌从 DTCG 源产出 CSS / JSON / TS 三种形态</li><li><strong>新增</strong> <code>@xihan-ui/styles</code> 纯 CSS 皮肤层，后续补上 reset 层</li><li><strong>新增</strong> <code>@xihan-ui/kernel</code> 全局诊断通道，状态机错误投递进该通道而不是抛在使用者脸上</li></ul><h3 id="适配器" tabindex="-1">适配器 <a class="header-anchor" href="#适配器" aria-label="Permalink to &quot;适配器&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/vue</code> Vue 3 适配器，Button / Dialog 纵切片先打穿全链路</li><li><strong>新增</strong> <code>@xihan-ui/web-components</code> Web Components 适配器，Light DOM 行为宿主；<code>xh-dialog</code> 把「有状态组件也能框架无关」这件事验证掉</li><li><strong>新增</strong> WC 侧观察 Light DOM 增删并重新接线，抹平「运行期增删条目」上的适配器分叉</li><li><strong>新增</strong> WC 角色节点契约校验与 Custom Elements Manifest 生成，两者都进门禁</li><li><strong>新增</strong> 跨适配器一致性套件（conformance）：同一批判据在两套宿主上逐帧比对归一化后的 DOM，套件数从 1 个扩到 102 个，排除项改为显式登记</li><li><strong>调整</strong> playground 拆成 <code>playground-vue</code> 与 <code>playground-wc</code> 两个独立包，一环境一包</li></ul><h3 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h3><ul><li><strong>新增</strong> 102 个组件逐批铺开，每个都同时产出无头内核、Vue 组件、自定义元素与默认皮肤：从 Button / Dialog 起，经 Switch、Checkbox / Collapsible / Separator、Toggle / Progress / Badge、RadioGroup / Tabs / Accordion、Tooltip / Popover、Menu、Select / Avatar / Field、NumberField，到日期族与最后一批，双适配器铺满</li><li><strong>新增</strong> alert / spinner / skeleton / empty-state 四个反馈类组件</li><li><strong>新增</strong> Checkbox 三态</li><li><strong>调整</strong> Select 支持多选，选中值由单值改为集合：<code>SelectValueChangeDetails.value</code> 由 <code>string | null</code> 变 <code>string[]</code>，<code>SelectApi</code> 的 <code>value</code> / <code>valueText</code> 变数组，<code>setValue</code> 签名变 <code>(next: string | string[]) =&gt; void</code>；Vue 侧 <code>update:value</code> 载荷与 WC 侧 <code>value-change</code> 的 <code>detail</code> 随之变化。见<a href="./components/select">选择器</a></li></ul><h3 id="视觉词汇表" tabindex="-1">视觉词汇表 <a class="header-anchor" href="#视觉词汇表" aria-label="Permalink to &quot;视觉词汇表&quot;">​</a></h3><ul><li><strong>新增</strong> 三个正交的视觉轴：<code>variant</code> 形态（<code>solid</code> / <code>subtle</code> / <code>outline</code> / <code>ghost</code>）、<code>tone</code> 语气（<code>brand</code> / <code>neutral</code> / <code>success</code> / <code>warning</code> / <code>danger</code> / <code>info</code>）、<code>size</code> 尺寸（<code>sm</code> / 缺省 / <code>lg</code>）。语气做成与组件无关的共享一层，各组件的形态规则只消费它声明的私有槽——加一个语气改一处，不是逐个组件写六遍</li><li><strong>新增</strong> 34 个组件接入这套词汇表：按钮族与表单控件、十个输入类组件、以及标签页、步骤条、菜单族、分页、表格、对话框、抽屉等。没写轴的组件外观与接入前逐值一致</li><li><strong>调整</strong> 实心底上的前景色按实测对比度分派而非统一白字：600 档上白字对 brand 5.08、neutral 7.80、danger 4.83 达标，而 success 3.04、warning 2.70、info 3.47 都不到 4.5，这三族配深字</li><li><strong>调整</strong> 破坏性变更：<code>alert</code> 的 <code>variant</code> 改名为 <code>tone</code>。它原本的取值是 <code>success</code> / <code>warning</code> / <code>danger</code>——那是语气不是形态，与全库词汇表冲突。取值不变，只改属性名；同时移除公开导出的 <code>AlertVariant</code> 类型</li><li><strong>调整</strong> <code>toast</code> 的配色改走共享语气层，由 <code>type</code> 内部派生（<code>error</code> → <code>danger</code>，<code>loading</code> → 中性），公开 API 不变</li><li><strong>调整</strong> 三条轴由裸 <code>string</code> 收成联合类型，从 <code>@xihan-ui/kernel</code> 导出：<code>Tone</code>（六档）、<code>Size</code>（<code>sm</code> / <code>md</code> / <code>lg</code>）、<code>ControlVariant</code>（<code>outline</code> / <code>subtle</code> / <code>ghost</code>，十二个输入控件）与 <code>ActionVariant</code>（前者再加 <code>solid</code>，按钮族）</li><li><strong>修复</strong> <code>checkbox</code> 半选态的横杠此前不可见：方框只在全选时填色，半选保持画布底，而横杠用的是实心底上的前景色，白压白等于没画</li></ul><h3 id="自研替换第三方" tabindex="-1">自研替换第三方 <a class="header-anchor" href="#自研替换第三方" aria-label="Permalink to &quot;自研替换第三方&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/position</code> 自研浮层定位引擎（包含块解析、缩放换算、翻面与避让、跟随更新），<strong>移除</strong> <code>@floating-ui/dom</code></li><li><strong>新增</strong> 自研虚拟滚动内核，<strong>移除</strong> <code>@tanstack/virtual-core</code></li><li><strong>新增</strong> WC 自研响应式基类，<strong>移除</strong> <code>@lit/reactive-element</code></li><li><strong>新增</strong> <code>@xihan-ui/markdown</code> 自研解析与渲染，<strong>移除</strong> <code>markdown-it</code></li><li><strong>新增</strong> 代码着色走端口，内置自研粗粒度词法器，可换 Shiki</li><li><strong>调整</strong> 至此全部库包的运行时第三方依赖只剩一个（<code>@internationalized/date</code>，仅日期族使用）。见<a href="./npm-package-dependency">包与依赖关系</a></li></ul><h3 id="ai-与-markdown" tabindex="-1">AI 与 Markdown <a class="header-anchor" href="#ai-与-markdown" aria-label="Permalink to &quot;AI 与 Markdown&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/chat-stream</code> 协议内核与 AI 组件族第一批：SSE 读取、协议归一、parts 归约、会话 store，配 Thread / Composer / CodeBlock 三件与粘底原语，双适配器</li><li><strong>新增</strong> <code>@xihan-ui/markdown</code> 流式渲染内核，增量切块 + 稳定 key + 消毒</li><li><strong>优化</strong> Markdown 接上 CommonMark 官方用例的一致率棘轮，逐步实现缩进代码块、Setext 标题、跨行链接引用定义与列表松紧排布，一致率由 375 提升至 489</li></ul><h3 id="视觉层" tabindex="-1">视觉层 <a class="header-anchor" href="#视觉层" aria-label="Permalink to &quot;视觉层&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/backgrounds</code>：WebGL2 背景效果与数据驱动粒子点云，框架无关、零第三方依赖。流场跑片元着色器、粒子走 <code>gl.POINTS</code>，两通道共用同一段 GLSL；内置 14 个效果，不支持 WebGL2 时降级为 CSS 静态背景</li><li><strong>新增</strong> 两个适配器接上视觉层，各走独立子入口 <code>@xihan-ui/vue/backgrounds</code> 与 <code>@xihan-ui/web-components/backgrounds</code>，<code>@xihan-ui/backgrounds</code> 声明为可选 peer</li><li><strong>修复</strong> 修复画面在真实页面里一片空白的三个成因</li></ul><h3 id="图标" tabindex="-1">图标 <a class="header-anchor" href="#图标" aria-label="Permalink to &quot;图标&quot;">​</a></h3><ul><li><strong>新增</strong> Icon 原语：<code>IconRecord</code> / <code>IconNode</code> / <code>IconTag</code> 类型、<code>connectIcon</code>、<code>XhIcon</code>、<code>&lt;xh-icon&gt;</code> 与 <code>icon.css</code>。图标数据是结构化节点数组而非 SVG 字符串，渲染端逐节点建元素，运行期不经 HTML 解析器</li><li><strong>移除</strong> 旧 <code>@xihan-ui/icons</code>（27 个第三方图标集的聚合，约四万个图标）整包移除并在 npm 上弃用，重写为只收自研图标的首方集，第一批 29 个覆盖组件库自用的全部语义</li></ul><h3 id="无障碍与质量门禁" tabindex="-1">无障碍与质量门禁 <a class="header-anchor" href="#无障碍与质量门禁" aria-label="Permalink to &quot;无障碍与质量门禁&quot;">​</a></h3><ul><li><strong>新增</strong> 无障碍扫描接上真实浏览器 runner 与 axe，逐个组件扫</li><li><strong>新增</strong> 键盘规格表机读化，作为测试的分母：用例少覆盖一条即判套件失败</li><li><strong>新增</strong> 产物契约门禁（publint + attw）、foundation 层框架无关门禁、依赖拓扑门禁</li><li><strong>修复</strong> 存量无障碍违规登记表清零，由 24 条降到 2 条（WC 侧 <code>steps</code> 一条，外加一条步骤重放豁免）</li><li><strong>修复</strong> 令牌 <code>fg-subtle</code> 达到 AA，并给对比度立下判据</li><li><strong>修复</strong> 焦点陷阱抓不住第一次逃逸；移除持有焦点的条目后不再让整组脱离 Tab 序列；删掉文件上传条目后把焦点交回投放区</li><li><strong>修复</strong> 浮层族改用 fixed 坐标系，不再被 overflow 祖先裁掉</li><li><strong>修复</strong> 挡住输入法组合态</li><li><strong>修复</strong> Dialog 三处：模态背景失活、非模态焦点域、收起态 hidden</li><li><strong>修复</strong> Field 的名字关联不再依赖 control 是可标注元素；Splitter root 不再输出 <code>aria-orientation</code></li><li><strong>修复</strong> 消解层只在展开期间入栈，不再与开合无关地常驻</li><li><strong>修复</strong> 状态机停机后送入的事件一律静默丢弃，dev 下不再抛</li></ul><h3 id="工程" tabindex="-1">工程 <a class="header-anchor" href="#工程" aria-label="Permalink to &quot;工程&quot;">​</a></h3><ul><li><strong>调整</strong> 皮肤层令牌成为唯一事实源，删掉全部字面量兜底，跨组件共享的默认值全部令牌化</li><li><strong>调整</strong> 全仓注释改为只讲功能，不带设计过程引用</li><li><strong>调整</strong> 行尾一律 LF（<code>.gitattributes</code>），署名统一为 XiHanFun and contributors</li><li><strong>新增</strong> changesets 发布配置就绪：14 个公开包锁步同版，私有包不发布不计版</li></ul>',39)])])}const u=e(c,[["render",r]]);export{h as __pageData,u as default};
